import { Link } from 'react-router-dom';

import { success } from '@helpers/notificationHelper';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohContainer from '@ui-kit/layout/Container';
import PohList from '@ui-kit/List';

import { addObstacleModalAsync } from '../ObstacleModal/modalHelper';

const ObstaclesPage = () => {
  const handleAdd = () => {
    addObstacleModalAsync().then((newObstacle) => success('Добавлено ' + newObstacle.name));
  };
  return (
    <div>
      <Breadcrumb data={[{ href: '/obstacles', text: 'Локальные препятствия', active: true }]} />
      <PohContainer>
        <header className="d-flex justify-content-between align-items-center d-print-none">
          <h3 className="mb-3">Локальные препятствия и точки интереса (POI)</h3>
          <PohButton size={ButtonSize.Small} variant={ButtonVariant.Success} onClick={handleAdd}>
            Добавить
          </PohButton>
        </header>
        <PohList
          data={[
            {
              key: 'peaks',
              content: 'Вершины',
              as: Link,
              to: `/obstacles/peaks`,
              action: true,
            },
            {
              key: 'passes',
              content: 'Перевалы',
              as: Link,
              to: `/obstacles/passes`,
              action: true,
            },
            {
              key: 'poi',
              content: 'Точки интереса (POI)',
              as: Link,
              to: `/obstacles/poi`,
              action: true,
            },
          ]}
        />
      </PohContainer>
    </div>
  );
};

export default ObstaclesPage;
